const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Asir, Saudi Arabia geometry (approximate bounding box)
  const asir = ee.Geometry.Rectangle([42.0, 17.0, 45.0, 20.0]);

  // Function to mask clouds using QA band
  function maskClouds(img) {
    const qa = img.select('BQA');
    const mask = qa.lt(2720); // Keep only clear/water pixels
    return img.updateMask(mask).select(['B4', 'B5']); // Red, NIR
  }

  // Function to calculate NDVI
  function calcNDVI(img) {
    const ndvi = img.normalizedDifference(['B5', 'B4']);
    return ndvi.rename('NDVI');
  }

  // Baseline period: June 2003-2011
  const baseline = ee.ImageCollection('LANDSAT/LM05/C02/T1_L2')
    .filterBounds(asir)
    .filterDate('2003-06-01', '2011-06-30')
    .filter(ee.Filter.calendarRange(6, 6, 'month'))
    .map(maskClouds)
    .map(calcNDVI);

  const baselineSize = baseline.size().getInfo();
  console.log(`Baseline (2003-2011) Images: ${baselineSize}`);

  if (baselineSize === 0) {
    console.log('Trying Landsat 8 for baseline...');
    const baseline8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(asir)
      .filterDate('2003-06-01', '2011-06-30')
      .filter(ee.Filter.calendarRange(6, 6, 'month'))
      .map(maskClouds)
      .map(calcNDVI);
    const bs8 = baseline8.size().getInfo();
    if (bs8 === 0) {
      console.log('No baseline data available.');
      console.log('C1');
      return;
    }
  }

  // Comparison period: June 2016 & 2017
  const comp2016 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(asir)
    .filterDate('2016-06-01', '2016-06-30')
    .map(maskClouds)
    .map(calcNDVI);

  const comp2017 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(asir)
    .filterDate('2017-06-01', '2017-06-30')
    .map(maskClouds)
    .map(calcNDVI);

  const c2016Size = comp2016.size().getInfo();
  const c2017Size = comp2017.size().getInfo();
  console.log(`2016 Images: ${c2016Size}, 2017 Images: ${c2017Size}`);

  if (c2016Size === 0 || c2017Size === 0) {
    console.log('C1');
    return;
  }

  // Calculate mean NDVI for each period
  const baselineMean = baseline.mean();
  const comp2016Mean = comp2016.mean();
  const comp2017Mean = comp2017.mean();

  // Get pixel counts to detect C2
  const baselineCount = baselineMean
    .reduceRegion(reducer = ee.Reducer.count(), geometry = asir, scale = 1000, maxPixels = 1e9)
    .get('NDVI').getInfo();

  const comp2016Count = comp2016Mean
    .reduceRegion(reducer = ee.Reducer.count(), geometry = asir, scale = 1000, maxPixels = 1e9)
    .get('NDVI').getInfo();

  if (baselineCount === 0 || comp2016Count === 0) {
    console.log('No valid pixels after masking.');
    console.log('C2');
    return;
  }

  // Calculate mean values
  const baselineVal = baselineMean
    .reduceRegion(reducer = ee.Reducer.mean(), geometry = asir, scale = 1000, maxPixels = 1e9)
    .get('NDVI').getInfo();

  const comp2016Val = comp2016Mean
    .reduceRegion(reducer = ee.Reducer.mean(), geometry = asir, scale = 1000, maxPixels = 1e9)
    .get('NDVI').getInfo();

  const comp2017Val = comp2017Mean
    .reduceRegion(reducer = ee.Reducer.mean(), geometry = asir, scale = 1000, maxPixels = 1e9)
    .get('NDVI').getInfo();

  if (baselineVal === null || comp2016Val === null || comp2017Val === null || 
      isNaN(baselineVal) || isNaN(comp2016Val) || isNaN(comp2017Val)) {
    console.log('Calculation failed (NaN or null).');
    console.log('C3');
    return;
  }

  // Validation: check NDVI range
  if (baselineVal < -1 || baselineVal > 1 || comp2016Val < -1 || comp2016Val > 1 || comp2017Val < -1 || comp2017Val > 1) {
    console.log('Invalid NDVI range detected.');
    console.log('C3');
    return;
  }

  const compAvg = (comp2016Val + comp2017Val) / 2;
  console.log(`Baseline (2003-2011) NDVI: ${baselineVal.toFixed(4)}, Pixels: ${Math.round(baselineCount)}`);
  console.log(`2016 NDVI: ${comp2016Val.toFixed(4)}, 2017 NDVI: ${comp2017Val.toFixed(4)}`);
  console.log(`Comparison Avg (2016+2017): ${compAvg.toFixed(4)}`);
  console.log(`Difference: ${(compAvg - baselineVal).toFixed(4)}`);

  if (compAvg > baselineVal) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
